examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    HStack(alignment: .top, spacing: MonarchTokens.Space.space3) {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
            HStack(spacing: MonarchTokens.Space.space2) {
                Text({{title}})
                    .monarchTextStyle(.title)
                    .accessibilityAddTraits(.isHeader)
                MonarchStatusBadge(MonarchStatusDefinition({{status.label}}, tone: {{status.tone|tone}}, systemImage: "checkmark.circle"))
            }
            Text({{subtitle}})
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textMuted)
        }
        Spacer()
        MonarchButton({{action}}, variant: .secondary, size: .sm) {}
    }
    MonarchKeyValue(
        [
            MonarchKeyValueItem({{facts.0.term}}, value: {{facts.0.value}}),
            MonarchKeyValueItem({{facts.1.term}}, value: {{facts.1.value}}),
        ],
        separator: .none,
        layout: .stack
    )
    MonarchTabs(
        "Record sections",
        selection: $tab,
        items: [
            MonarchTabsItem({{tabs.0.label}}, value: {{tabs.0.value}}),
            MonarchTabsItem({{tabs.1.label}}, value: {{tabs.1.value}}, count: String({{tabs.1.count}})),
            MonarchTabsItem({{tabs.2.label}}, value: {{tabs.2.value}}),
        ]
    )
    if tab == {{tabs.0.value}} {
        Text({{tabs.0.content}}).monarchTextStyle(.body)
    } else if tab == {{tabs.1.value}} {
        Text({{tabs.1.content}}).monarchTextStyle(.body)
    } else {
        Text({{tabs.2.content}}).monarchTextStyle(.body)
    }
    Text({{aside}}).monarchTextStyle(.body)
    Text("Activity")
        .monarchTextStyle(.label)
        .accessibilityAddTraits(.isHeader)
    Text({{activity}}).monarchTextStyle(.body)
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    HStack(alignment: .top, spacing: MonarchTokens.Space.space3) {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
            HStack(spacing: MonarchTokens.Space.space2) {
                Text("Sample record")
                    .monarchTextStyle(.title)
                    .accessibilityAddTraits(.isHeader)
                MonarchStatusBadge(MonarchStatusDefinition("Active", tone: .success, systemImage: "checkmark.circle"))
            }
            Text("REC-0001")
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textMuted)
        }
        Spacer()
        MonarchButton("Edit", variant: .secondary, size: .sm) {}
    }
    MonarchKeyValue(
        [
            MonarchKeyValueItem("Owner", value: "Person A"),
            MonarchKeyValueItem("Created", value: "1 June 2026"),
        ],
        separator: .none,
        layout: .stack
    )
    MonarchTabs(
        "Record sections",
        selection: $tab,
        items: [
            MonarchTabsItem("Overview", value: "overview"),
            MonarchTabsItem("Notes", value: "notes", count: String(2)),
            MonarchTabsItem("Files", value: "files"),
        ]
    )
    if tab == "overview" {
        Text("Overview content for the sample record.").monarchTextStyle(.body)
    } else if tab == "notes" {
        Text("Two sample notes.").monarchTextStyle(.body)
    } else {
        Text("No files yet.").monarchTextStyle(.body)
    }
    Text("Properties and related records go here.").monarchTextStyle(.body)
    Text("Activity")
        .monarchTextStyle(.label)
        .accessibilityAddTraits(.isHeader)
    Text("Sample activity entries go here.").monarchTextStyle(.body)
}
